197	func compareLiterals(left any, op ComparisonOperator, right any) (bool, error) {
198		if l, r, ok := asFloats(left, right); ok {
199			switch op {
200			case CompareEq:
201				return l == r, nil
202			case CompareNeq:
203				return l != r, nil
204			case CompareLt:
205				return l < r, nil
206			case CompareLte:
207				return l <= r, nil
208			case CompareGt:
209				return l > r, nil
210			case CompareGte:
211				return l >= r, nil
212			}
213		}
214		if l, ok := left.(string); ok {
215			if r, ok := right.(string); ok {
216				switch op {
217				case CompareEq:
218					return l == r, nil
219				case CompareNeq:
220					return l != r, nil
221				case CompareLt:
222					return l < r, nil
223				case CompareLte:
224					return l <= r, nil
225				case CompareGt:
226					return l > r, nil
227				case CompareGte:
